package dev.henrique.inventory.api;
import static dev.henrique.inventory.api.ApiModels.*; import dev.henrique.inventory.domain.*; import dev.henrique.inventory.service.ResourceNotFoundException; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { private ResponseEntity<ApiError> error(HttpStatus s,String code,String msg,String path,Map<String,String>d){return ResponseEntity.status(s).body(new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),code,msg,path,d));}
 @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ApiError> notFound(RuntimeException e,HttpServletRequest r){return error(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND",e.getMessage(),r.getRequestURI(),Map.of());}
 @ExceptionHandler(InsufficientInventoryException.class) ResponseEntity<ApiError> insufficient(RuntimeException e,HttpServletRequest r){return error(HttpStatus.CONFLICT,"INSUFFICIENT_INVENTORY",e.getMessage(),r.getRequestURI(),Map.of());}
 @ExceptionHandler(InvalidTransitionException.class) ResponseEntity<ApiError> transition(RuntimeException e,HttpServletRequest r){return error(HttpStatus.CONFLICT,"INVALID_RESERVATION_TRANSITION",e.getMessage(),r.getRequestURI(),Map.of());}
 @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ApiError> validation(MethodArgumentNotValidException e,HttpServletRequest r){Map<String,String>d=new TreeMap<>();e.getBindingResult().getFieldErrors().forEach(x->d.putIfAbsent(x.getField(),x.getDefaultMessage()));return error(HttpStatus.BAD_REQUEST,"VALIDATION_FAILED","Request validation failed",r.getRequestURI(),d);}
}
